-- Vorrats-Aufgaben (rollend-4) in bestehende Flüge einfügen: 7 Aufgaben, 6 Einheiten, mit form und zaehlt (FT-S). Ein Aufruf, eine Transaktion.
select set_config('lock_timeout', '3s', true), set_config('statement_timeout', '60s', true);
do $einspielen$
declare e record; n int; vorher int; gesamt int := 0; fehler text[] := '{}';
begin
  if (select count(*) from pg_attribute where attrelid = 'schule.aufgabe'::regclass and attname in ('form', 'zaehlt') and not attisdropped) <> 2
     or position('x->>''form''' in pg_get_functiondef('schule.aufgaben_einfuegen(bigint, jsonb)'::regprocedure)) = 0 then
    raise exception 'Vorrats-Aufgaben: erst FT-S einspielen (Spalten form/zaehlt, aufgaben_einfuegen)'; end if;
  for e in select * from (values
    (4, 'zahlen.teilbarkeit', 658, 2, $auf$[{"l": "endziffer", "t": "endziffer", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Die Zahl 7 360 wird durch 10 geteilt: 7 360 : 10 = ①. Die Endziffer von ① ist ②. Weil ② gerade ist, ist ① durch 2 teilbar: ① : 2 = ③. Die Endziffer von ③ ist ④.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [736, 6, 368, 8]}, "h": "Beim Teilen durch 10 fällt die letzte Null weg. Die Endziffer ist die letzte Ziffer einer Zahl.", "w": "7 360 : 10 = 736. Die Endziffer von 736 ist 6, eine gerade Ziffer, also ist 736 durch 2 teilbar: 736 : 2 = 368. Die Endziffer von 368 ist 8.", "form": "lueckenweg", "zaehlt": "nein", "r": 679}, {"l": "neunerregel", "t": "neunerregel", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Prüfe 5 481 auf Teilbarkeit durch 9. Quersumme: 5 + 4 + 8 + 1 = ①. Dann ① : 9 = ② ohne Rest, also ist 5 481 durch 9 teilbar. Der Unterschied zwischen einer Zahl und ihrer Quersumme ist immer durch 9 teilbar. Hier: 5 481 − ① = ③. Diese Zahl geteilt durch 9 ergibt ③ : 9 = ④.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [18, 2, 5463, 607]}, "h": "Zähle alle Ziffern zusammen und teile durch 9. Ziehe dann die Quersumme von der Zahl ab.", "w": "5 + 4 + 8 + 1 = 18. 18 : 9 = 2. 5 481 − 18 = 5 463. 5 463 : 9 = 607. Probe: 607 · 9 = 5 463.", "form": "lueckenweg", "zaehlt": "nein", "r": 680}]$auf$::jsonb),
    (6, 'gleichungen.einfach', 599, 1, $auf$[{"l": "ohne_loesung", "t": "loesbarkeit", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Die Gleichung x + 3 = x + 5 soll mit Hilfe von Geraden gedeutet werden. Angenommen, man zeichnet die Gerade y = x + 3 und die Gerade y = x + 5 in dasselbe Koordinatensystem. Was würde man dann sehen, und was folgt daraus für die Lösungen der Gleichung?"}, "a": ["Die Geraden sind parallel und haben keinen gemeinsamen Punkt: Die Gleichung hat keine Lösung.", "Die Geraden schneiden sich in genau einem Punkt: Die Gleichung hat genau eine Lösung.", "Die Geraden liegen aufeinander: Die Gleichung hat unendlich viele Lösungen.", "Die Geraden stehen senkrecht aufeinander: Die Gleichung hat zwei Lösungen."], "o": {"index": 0}, "h": "Ein gemeinsamer Punkt beider Geraden wäre eine Lösung der Gleichung. Vergleiche Steigung und Achsenabschnitt.", "w": "Beide Geraden haben die Steigung 1, aber verschiedene Achsenabschnitte (3 und 5). Sie sind parallel und haben keinen gemeinsamen Punkt. Rechnerisch: x abziehen gibt 3 = 5, eine falsche Aussage. Also keine Lösung.", "form": "bruecke", "zaehlt": "ja", "r": 625}]$auf$::jsonb),
    (17, 'funktionen.linear', 777, 1, $auf$[{"l": "ablesen", "t": "ablesen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Die Gleichung 2y = 6x + 8 wird durch 2 geteilt. Dann ist y = ①x + ②. Die Steigung ist ① und der Achsenabschnitt ist ②. Für x = 2 gehört dann der Wert y = ① · 2 + ② = ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [3, 4, 10]}, "h": "Teile beide Zahlen rechts durch 2.", "w": "6x : 2 = 3x und 8 : 2 = 4. Also y = 3x + 4. Für x = 2 ist y = 3 · 2 + 4 = 10.", "form": "lueckenweg", "zaehlt": "nein", "r": 801}]$auf$::jsonb),
    (47, 'geometrie.grundbegriffe', 622, 1, $auf$[{"l": "strecken", "t": "strecken", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim berechnet die Länge der Strecke [AB] mit A(−4 | 3) und B(5 | 3). Zeile 1: A und B haben beide y = 3. Die Strecke liegt waagrecht. Zeile 2: Die y-Achse liegt zwischen A und B. Kim behauptet: Die gesuchte Streckenlänge ist 5 − 4 = 1. Zeile 3: Die Strecke [AB] ist 1 Einheit lang. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Liegt die 0 zwischen den Punkten, was musst du dann tun?", "w": "Die y-Achse liegt zwischen A und B. Dann addierst du die Teile: 4 + 5 = 9. Richtig: 9 Einheiten.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 646}]$auf$::jsonb),
    (48, 'geometrie.ortslinien', 574, 1, $auf$[{"l": "sachsituationen", "t": "sachsituationen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein Rasensprenger steht 5 m von einem Zaun entfernt. Er spritzt 3 m weit. Kim fragt, ob der Zaun nass wird. Zeile 1: Die nasse Fläche ist ein Kreis um den Sprenger mit dem Radius 3 m. Zeile 2: Der Kreis ist 3 + 3 = 6 m breit. Der Zaun ist 5 m vom Sprenger entfernt. Weil 5 weniger als 6 ist, reicht das Wasser bis zum Zaun. Zeile 3: Also wird der Zaun nass. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Von wo aus wird die Entfernung zum Zaun gemessen, und wie weit reicht das Wasser von dort?", "w": "Die 6 m gelten von Rand zu Rand des Kreises, der Zaun wird aber vom Sprenger aus gemessen. Vom Sprenger reicht das Wasser nur 3 m, und der Zaun ist 5 m weg: Er bleibt trocken. Zeile 2 behauptet, dass 5 < 6 genügt; Zeile 3 folgt nur daraus.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 596}]$auf$::jsonb),
    (308, 'abbildungen.kongruenz_teil3', 751, 1, $auf$[{"l": "drehung", "t": "drehung", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "P(9 | 6) wird um Z(2 | 1) um 90° gegen den Uhrzeigersinn gedreht. Zuerst der Vektor von Z nach P: (9 − 2 | 6 − 1) = (① | ②). Die Drehung macht aus (a | b) den Vektor (−b | a). Der Bildpunkt ist Z plus dieser Vektor: P'(③ | ④).", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [7, 5, -3, 8]}, "h": "Erst der Vektor von Z nach P, dann nach der Regel drehen, dann zu Z addieren.", "w": "(9 − 2 | 6 − 1) = (7 | 5). Gedreht: (−5 | 7). P' = (2 − 5 | 1 + 7) = (−3 | 8).", "form": "lueckenweg", "zaehlt": "nein", "r": 756}]$auf$::jsonb)
  ) x(id, schluessel, max_r, soll, aufgaben) loop
    if not exists (select 1 from schule.einheit ei join schule.thema th on th.id = ei.thema_id where ei.id = e.id and th.schluessel = e.schluessel) then
      fehler := fehler || ('Einheit ' || e.id || ' ist nicht ' || e.schluessel)::text; continue; end if;
    if (select coalesce(max(reihenfolge), 0) from schule.aufgabe where einheit_id = e.id and pool = 'uebung' and reihenfolge <= e.max_r) <> e.max_r then
      fehler := fehler || ('Einheit ' || e.id || ': Bestand hat sich seit dem Lesen geändert')::text; continue; end if;
    if exists (select 1 from schule.aufgabe a where a.einheit_id = e.id and a.pool = 'uebung' and a.reihenfolge in (select (x->>'r')::int from jsonb_array_elements(e.aufgaben) x)) then
      fehler := fehler || ('Einheit ' || e.id || ': Reihenfolge-Nummern des Pakets sind schon belegt (Paket schon eingespielt?)')::text; continue; end if;
    if exists (select 1 from jsonb_array_elements(e.aufgaben) x where not exists (select 1 from schule.einheit ei, jsonb_array_elements(ei.inhalt->'etappen') et where ei.id = e.id and et->>'lernziel' = x->>'l')) then
      fehler := fehler || ('Einheit ' || e.id || ': Lernziel unbekannt')::text; continue; end if;
    select count(*) into vorher from schule.aufgabe where einheit_id = e.id;
    n := schule.aufgaben_einfuegen(e.id, e.aufgaben);
    if n <> e.soll or (select count(*) from schule.aufgabe where einheit_id = e.id) <> vorher + e.soll then
      fehler := fehler || ('Einheit ' || e.id || ': ' || n || ' statt ' || e.soll || ' eingefügt')::text; end if;
    if (select count(*) from schule.aufgabe a where a.einheit_id = e.id and a.reihenfolge in (select (x->>'r')::int from jsonb_array_elements(e.aufgaben) x) and a.pool = 'uebung' and a.form is not null and a.zaehlt is not null) <> e.soll then
      fehler := fehler || ('Einheit ' || e.id || ': form/zaehlt nicht übernommen')::text; end if;
    if exists (select 1 from schule.aufgabe a where a.einheit_id = e.id and a.reihenfolge in (select (x->>'r')::int from jsonb_array_elements(e.aufgaben) x) and a.pool = 'uebung'
               and not coalesce((schule.antwort_bewerten(a, case a.antworttyp when 'zahl' then jsonb_build_object('wert', '0') else '{}'::jsonb end)->>'format_ok') is not null, false)) then
      fehler := fehler || ('Einheit ' || e.id || ': eine neue Aufgabe lässt sich nicht bewerten')::text; end if;
    gesamt := gesamt + n;
  end loop;
  if gesamt <> 7 then fehler := fehler || ('zusammen ' || gesamt || ' statt 7')::text; end if;
  if array_length(fehler, 1) > 0 then raise exception 'Vorrats-Aufgaben ABBRUCH, alles zurückgerollt: %', array_to_string(fehler, ' | '); end if;
end $einspielen$;
select einheit_id, count(*) filter (where pool = 'uebung') as uebungen, count(*) filter (where form is not null) as mit_form from schule.aufgabe where einheit_id in (4, 6, 17, 47, 48, 308) group by 1 order by 1;
